from pg_class c join pg_namespace n on n.oid=c.relnamespace
where n.nspname='public' and c.relname='media';

-- storage bucket
select id, name, public from storage.buckets where id='farm-images' or name='farm-images';

-- storage policies on objects for farm-images
select polname, polcmd, pg_get_expr(polqual, polrelid) as using_expr,
  pg_get_expr(polwithcheck, polrelid) as check_expr
from pg_policy where polrelid='storage.objects'::regclass;

-- how many media rows exist
select type, count(*) from public.media group by type;

-- Farm Photos (and any media) failed to save: public.media had RLS enabled with
-- only a SELECT policy, so the farmer dashboard's anon insert was silently
-- rejected and the uploaded file never got a media row. Mirror the permissive
-- write policies already used on produce_listings so the localStorage-auth
-- farmer dashboard can add/update/remove its own farm photos.

drop policy if exists "Allow insert media" on public.media;
create policy "Allow insert media" on public.media
  for insert to anon
  with check (true);

drop policy if exists "media public update" on public.media;
create policy "media public update" on public.media
  for update
  using (true)
  with check (true);

drop policy if exists "media public delete" on public.media;
create policy "media public delete" on public.media
  for delete
  using (true);

