{/* Count only live listings — a produce the farmer has suspended (or that
    is still "coming soon") must not inflate the public "Produce now" stat. */}
<TrustStrip
  farmer={{ ...farmer, rating_avg: ratingAvg }}
  produceCount={(produce ?? []).filter((p) => (p as { status?: string }).status === 'available').length}
  chemicalListings={(produce ?? []).filter((p) => {
    const m = (p as { method?: string }).method
    const st = (p as { status?: string }).status
    return st === 'available' && (m === 'chemical' || m === 'low_chemical')
  }).length}
/>
<Suspense fallback={null}>
  <TabSection
    farmer={farmer}
    produce={produce ?? []}
    reviews={allReviews}
    produceReviews={produceReviewSummary}
    media={media ?? []}
  />
</Suspense>

