  produceCount: number
  // How many of the farm's live listings are grown with chemical / semi-organic
  // methods (driven by the farming method the farmer picks per produce). 0 means
  // every listing is natural or organic — the ideal "no chemicals" trust signal.
  chemicalListings?: number
}) {
  const { tx, L } = useLang()
  const yearsfarming = new Date().getFullYear() - farmer.farming_since_year

  const stats = [
    { label: tx.yearsFarming, value: yearsfarming.toString() },
    { label: tx.starRating, value: `${farmer.rating_avg} ★` },
    { label: tx.buyers, value: farmer.buyer_count.toString() },
    { label: tx.chemicals, value: chemicalListings.toString() },
    { label: tx.produceNow, value: `${produceCount}` },
  ]

  return (
    <div className="bg-white border-b border-gray-100">
      <div className="grid grid-cols-5 divide-x divide-gray-100">
        {stats.map((stat) => (
          <div key={stat.label} className="flex flex-col items-center py-3 px-1">
            <span className="text-base font-extrabold text-gray-900">{stat.value}</span>
            <span className="text-[11px] text-gray-500 text-center leading-tight mt-0.5">
              {stat.label}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

import { supabase } from '@/lib/supabase'
import { notFound } from 'next/navigation'

export const dynamic = 'force-dynamic'
import { Suspense } from 'react'
import TopNav from '@/components/farmer/TopNav'
import FarmCover from '@/components/farmer/FarmCover'
import TrustStrip from '@/components/farmer/TrustStrip'
import TabSection from '@/components/farmer/TabSection'
import { CartFab } from '@/components/consumer/Cart'

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params

  const { data: farmer } = await supabase
    .from('farmers')
    .select('id, name, village, district, story_quote')
    .eq('slug', slug)
    .single()

  if (!farmer) return { title: 'Farmer not found' }

  const { data: firstPhoto } = await supabase
    .from('media')
    .select('url')
    .eq('farmer_id', farmer.id)
    .eq('type', 'photo')
    .order('sort_order', { ascending: true })
    .limit(1)
    .single()

  const title = `${farmer.name} — Natural farmer in ${farmer.village}`
  const description =
    farmer.story_quote ??
    `Buy natural produce directly from ${farmer.name}, ${farmer.village}, ${farmer.district}. No middlemen. No chemicals.`

  return {
    title: `${farmer.name}'s Farm — YourFamilyFarmer`,
    description,
    openGraph: {
      title,
      description,
      siteName: 'YourFamilyFarmer',
      ...(firstPhoto?.url ? { images: [{ url: firstPhoto.url, width: 1200, height: 630, alt: `${farmer.name}'s farm` }] } : {}),
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
      ...(firstPhoto?.url ? { images: [firstPhoto.url] } : {}),
    },
  }
}

export default async function FarmerPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params

  const { data: farmer } = await supabase
    .from('farmers')
    .select('*')
    .eq('slug', slug)
    .eq('active', true)
    .single()

  if (!farmer) notFound()

  const { data: produce } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('farmer_id', farmer.id)
    .order('created_at', { ascending: false })

  const { data: reviews } = await supabase
    .from('reviews')
    .select('*')
    .eq('farmer_id', farmer.id)
    .eq('approved', true)
    .order('created_at', { ascending: false })

  // Verified per-order buyer feedback (the ⭐ button consumers tap on their
  // orders) lives in produce_reviews, tied to a listing. Only feedback on a
  // completed order is approved/public. Surface it on the farmer's profile too —
  // tagged with the produce it was about — so consumer feedback isn't invisible
  // here, and fold it into the same Reviews tab + star average as written reviews.
  const { data: produceReviews } = await supabase
    .from('produce_reviews')
    .select('id, reviewer_name, star_rating, review_text, created_at, produce_listing_id')
    .eq('farmer_id', farmer.id)
    .eq('approved', true)
    .order('created_at', { ascending: false })

  // Resolve the produce names with a separate query rather than a PostgREST
  // embedded join (produce_reviews → produce_listings). That relationship isn't
  // in the schema cache, so embedding it made the whole produce_reviews query
  // error out and return null — which silently hid ALL verified buyer feedback
  // from the profile (showing "No reviews yet" and a 0 rating even when approved
  // reviews existed).
  const listingIds = [
    ...new Set((produceReviews ?? []).map((r) => r.produce_listing_id).filter(Boolean) as string[]),
  ]
  const { data: listingNames } = listingIds.length
    ? await supabase.from('produce_listings').select('id, name').in('id', listingIds)
    : { data: [] as { id: string; name: string }[] }
  const nameById = new Map((listingNames ?? []).map((l) => [l.id, l.name]))

  const mappedProduceReviews = (produceReviews ?? []).map((r) => ({
    id: r.id,
    reviewer_name: r.reviewer_name,
    star_rating: r.star_rating,
    review_text: r.review_text,
    produce_ordered: r.produce_listing_id ? nameById.get(r.produce_listing_id) ?? null : null,
    created_at: r.created_at,
  }))

  // Both sources, newest first — one combined list for the Reviews tab.
  const allReviews = [...(reviews ?? []), ...mappedProduceReviews].sort(
    (a, b) => new Date(b.created_at as string).getTime() - new Date(a.created_at as string).getTime(),
  )

  // Per-listing rating summary so the Produce tab can show each produce's own
  // verified buyer feedback (avg stars, count, latest snippet) on its card —
  // produceReviews is already ordered newest-first, so the first hit per listing
  // is the latest review.
  const reviewAcc = new Map<string, { sum: number; count: number; latest: { name: string; text: string | null; stars: number } | null }>()
  for (const r of produceReviews ?? []) {
    if (!r.produce_listing_id) continue
    const cur = reviewAcc.get(r.produce_listing_id) ?? { sum: 0, count: 0, latest: null }
    cur.sum += (r.star_rating as number) ?? 0
    cur.count += 1
    if (!cur.latest) cur.latest = { name: r.reviewer_name, text: r.review_text, stars: (r.star_rating as number) ?? 0 }
    reviewAcc.set(r.produce_listing_id, cur)
  }
  const produceReviewSummary: Record<string, { avg: number; count: number; latest: { name: string; text: string | null; stars: number } | null }> = {}
  reviewAcc.forEach((v, k) => {
    produceReviewSummary[k] = { avg: Math.round((v.sum / v.count) * 10) / 10, count: v.count, latest: v.latest }
  })

  // Star rating shown in the trust strip reflects all real feedback (written
  // reviews + verified order feedback). Falls back to the stored value if there
  // are no reviews yet.
  const ratingAvg =
    allReviews.length > 0
      ? Math.round(
          (allReviews.reduce((sum, r) => sum + ((r.star_rating as number) ?? 0), 0) / allReviews.length) * 10,
        ) / 10
      : (farmer.rating_avg ?? 0)

  const { data: media } = await supabase
    .from('media')
    .select('*')
    .eq('farmer_id', farmer.id)
    .order('sort_order', { ascending: true })

  return (
    <main className="min-h-screen bg-gray-50 pb-24">
      <TopNav regionSlug={farmer.region_slug} />
      <FarmCover farmer={farmer} />
      {/* Count only live listings — a produce the farmer has suspended (or that
          is still "coming soon") must not inflate the public "Produce now" stat. */}
      <TrustStrip
        farmer={{ ...farmer, rating_avg: ratingAvg }}
        produceCount={(produce ?? []).filter((p) => (p as { status?: string }).status === 'available').length}
        chemicalListings={(produce ?? []).filter((p) => {
          const m = (p as { method?: string }).method
          const st = (p as { status?: string }).status
          return st === 'available' && (m === 'chemical' || m === 'low_chemical')
        }).length}
      />
      <Suspense fallback={null}>
        <TabSection
          farmer={farmer}
          produce={produce ?? []}
          reviews={allReviews}
          produceReviews={produceReviewSummary}
          media={media ?? []}
        />
      </Suspense>
      <CartFab />
    </main>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useLang } from '@/lib/LanguageContext'

type Farmer = {
  name: string
  village: string
  district: string
  state: string
  farming_since_year: number
  cover_photo_url?: string | null
  photo_url?: string | null
  phone?: string | null
}

export default function FarmCover({ farmer }: { farmer: Farmer }) {
  const { tx, L } = useLang()
  const [followed, setFollowed] = useState(false)
  const [lightbox, setLightbox] = useState(false)

  useEffect(() => {
    const saved = localStorage.getItem(`follow_${farmer.name}`)
    if (saved) setFollowed(true)
  }, [farmer.name])

  const toggleFollow = () => {
    if (followed) {
      localStorage.removeItem(`follow_${farmer.name}`)
      setFollowed(false)
    } else {
      localStorage.setItem(`follow_${farmer.name}`, 'true')
      setFollowed(true)
    }
  }

  const initials = farmer.name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2)

  // Quick "Schedule a Visit" — opens WhatsApp to the farmer (same intent as the
  // detailed visit card in the Story tab), surfaced right next to the name.
  const whatsappVisitLink = farmer.phone
    ? `https://wa.me/${farmer.phone.replace(/\D/g, '')}?text=${encodeURIComponent(
        tx.visitWhatsApp.replace('{name}', farmer.name ?? ''),
      )}`
    : null

  return (
    <div className="relative">
      {/* Cover — real photo if uploaded, SVG illustration otherwise */}
      <div className="relative w-full h-44 bg-green-800 overflow-hidden">
        {farmer.cover_photo_url ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={farmer.cover_photo_url}
            alt={`${farmer.name}'s farm`}
            className="w-full h-full object-cover"
          />
        ) : (
          <svg viewBox="0 0 390 176" className="w-full h-full" preserveAspectRatio="xMidYMid slice">
            <rect width="390" height="176" fill="#1a4a1a" />
            <circle cx="320" cy="40" r="28" fill="#f9c74f" opacity="0.9" />
            <circle cx="320" cy="40" r="22" fill="#f9c74f" />
            {[0,45,90,135,180,225,270,315].map((angle, i) => (
              <line key={i}
                x1={320 + Math.cos((angle * Math.PI) / 180) * 26}
                y1={40 + Math.sin((angle * Math.PI) / 180) * 26}
                x2={320 + Math.cos((angle * Math.PI) / 180) * 36}
                y2={40 + Math.sin((angle * Math.PI) / 180) * 36}
                stroke="#f9c74f" strokeWidth="2.5"
              />
            ))}
            <rect x="0" y="130" width="390" height="46" fill="#2d5a1b" />
            <rect x="0" y="138" width="390" height="38" fill="#3a7a24" />
            <rect x="30" y="90" width="10" height="50" fill="#5c3d11" />
            <circle cx="35" cy="80" r="28" fill="#2d8a1f" />
            <circle cx="20" cy="90" r="18" fill="#33991f" />
            <circle cx="50" cy="88" r="20" fill="#267a18" />
            <rect x="340" y="95" width="10" height="45" fill="#5c3d11" />
            <circle cx="345" cy="82" r="26" fill="#2d8a1f" />
            <circle cx="330" cy="92" r="17" fill="#33991f" />
            <circle cx="358" cy="90" r="19" fill="#267a18" />
            {[0,1,2,3,4].map((i) => (
              <g key={i}>
                <line x1={120 + i * 32} y1="145" x2={120 + i * 32} y2="118" stroke="#4caf50" strokeWidth="2" />
                <ellipse cx={120 + i * 32} cy="116" rx="8" ry="12" fill="#66bb6a" />
                <ellipse cx={116 + i * 32} cy="122" rx="6" ry="9" fill="#81c784" />
                <ellipse cx={124 + i * 32} cy="121" rx="6" ry="9" fill="#81c784" />
              </g>
            ))}
            <rect x="165" y="110" width="60" height="35" fill="#8b6914" />
            <polygon points="155,112 195,88 235,112" fill="#a0522d" />
            <rect x="185" y="125" width="18" height="20" fill="#5c3d11" />
            <rect x="0" y="158" width="390" height="8" fill="#1565c0" opacity="0.6" />
            <rect x="0" y="159" width="390" height="4" fill="#42a5f5" opacity="0.4" />
          </svg>
        )}

        <div className="absolute top-3 left-3 bg-white/90 backdrop-blur-sm rounded-full px-3 py-1 text-xs font-semibold text-green-800">
          {L('Natural farm', 'సహజ పొలం')} · {L('since', 'నుండి')} {farmer.farming_since_year}
        </div>
      </div>

      {/* Identity section */}
      <div className="bg-white px-4 pt-4 pb-4">
        <div className="flex items-start justify-between gap-3">
          <div className="flex items-center gap-3">
            {/* Avatar — real photo if uploaded, initials otherwise */}
            <div className="flex-shrink-0 -mt-8">
              {farmer.photo_url ? (
                <button
                  type="button"
                  onClick={() => setLightbox(true)}
                  className="block rounded-full focus:outline-none"
                  aria-label="View full photo"
                >
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img
                    src={farmer.photo_url}
                    alt={farmer.name}
                    className="w-14 h-14 rounded-full object-cover border-3 border-white shadow-md"
                  />
                </button>
              ) : (
                <div className="w-14 h-14 rounded-full bg-green-700 flex items-center justify-center text-white font-bold text-lg border-3 border-white shadow-md">
                  {initials}
                </div>
              )}
            </div>
            <div>
              <h1 className="text-lg font-bold text-gray-900">{farmer.name}</h1>
              <p className="text-sm text-gray-500">
                {farmer.village}, {farmer.district}, {farmer.state}
              </p>
            </div>
          </div>

          <div className="flex-shrink-0 flex flex-col items-end gap-2 mt-1">
            {whatsappVisitLink && (
              <a
                href={whatsappVisitLink}
                target="_blank"
                rel="noopener noreferrer"
                className="px-4 py-1.5 rounded-full text-sm font-semibold bg-amber-500 text-white whitespace-nowrap active:bg-amber-600"
              >
                📅 {tx.scheduleVisit}
              </a>
            )}
            <button
              onClick={toggleFollow}
              className={`px-4 py-1.5 rounded-full text-sm font-semibold border transition-all ${
                followed
                  ? 'bg-green-700 text-white border-green-700'
                  : 'bg-white text-green-700 border-green-700'
              }`}
            >
              {followed ? tx.following : tx.follow}
            </button>
          </div>
        </div>
      </div>

      {/* Full-size photo lightbox */}
      {lightbox && farmer.photo_url && (
        <button
          type="button"
          onClick={() => setLightbox(false)}
          className="fixed inset-0 z-[200] bg-black/90 flex items-center justify-center p-4"
          aria-label="Close photo"
        >
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={farmer.photo_url}
            alt={farmer.name}
            className="max-w-full max-h-full rounded-2xl object-contain shadow-2xl"
          />
        </button>
      )}
    </div>
  )
}

